func testDespesasToManyAddOpDespContratoEntidadeTipos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Despesas
	var b, c, d, e ContratoEntidadeTipo

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, despesasDBTypes, false, strmangle.SetComplement(despesasPrimaryKeyColumns, despesasColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*ContratoEntidadeTipo{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, contratoEntidadeTipoDBTypes, false, strmangle.SetComplement(contratoEntidadeTipoPrimaryKeyColumns, contratoEntidadeTipoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*ContratoEntidadeTipo{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddDespContratoEntidadeTipos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if !queries.Equal(a.DespID, first.DespID) {
			t.Error("foreign key was wrong value", a.DespID, first.DespID)
		}
		if !queries.Equal(a.DespID, second.DespID) {
			t.Error("foreign key was wrong value", a.DespID, second.DespID)
		}

		if first.R.Desp != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Desp != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.DespContratoEntidadeTipos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.DespContratoEntidadeTipos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.DespContratoEntidadeTipos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

